/**
 * Proposal PDF Generator
 * Generates a professional proposal document for the insured to review and sign
 */


export interface ProposalData {
	// Quote Information
	quoteNumber: string;
	proposalDate: string;
	desiredCoverageDates?: string;
	agentName?: string;
	agencyAddress?: string;
	agencyState?: string;
	agencyZip?: string;
	agencyCity?: string;
	classCode?: string;
	isExcessOnlyProposal?: boolean;
	// Insured Information
	companyName?: string;
	dba?: string;
	firstName?: string;
	lastName?: string;
	entityType?: string;
	companyFEIN?: string;
	phone?: string;
	email?: string;
	streetAddress?: string;
	city?: string;
	state?: string;
	zipCode?: string;
	grossReceipts?: string;

	// Agency Information
	agencyName?: string;
	agencyEmail?: string;
	agencyPhone?: string;

	// Carrier Information
	carrierName?: string;
	carrierNameXL?: string;
	carrierReference?: string;

	// Policy Information
	programName?: string;
	effectiveDate?: string;
	expirationDate?: string;
	occurrenceLimit?: string;
	productsCompletedOpsLimit?: string;
	personalAdvertisingInjuryLimit?: string;
	fireLegalLimit?: string;
	medPayLimit?: string;
	aggregateLimit?: string;
	deductible?: string;
	selfInsuredRetention?: string;


	// Premium Breakdown
	carrierQuoteUSD?: number;
	// No wholesale fee - removed per user request
	premiumTaxPercent?: number;
	premiumTaxAmountUSD?: number;
	addExcessLiability?: boolean;
	excessLiabilityAmount?: number;
	excessLiabilityLimit?: string;
	policyFeeUSD?: number;
	brokerFeeAmountUSD?: number;
	finalAmountUSD?: number;
	subcontractorCosts?: string;

	// Limits
	limits?: {
		generalLiability?: string;
		aggregateLimit?: string;
		fireLegalLimit?: string;
		medPayLimit?: string;
		deductible?: string;
	};

	// Endorsements
	endorsements?: string[];

	// Special Notes
	specialNotes?: string;
	contactPerson?: string;

	// Additional Data
	applicationId?: string | number;
	capitalCoLogoSVG?: string;
	employeePayroll?: string;
	descriptionOfOperations?: string;
}

